const BLOCK_CONTROLS = [
  { id: "blkDayStart", label: "Your day start", pick: (d) => d.dayStart },
  { id: "blkDayEnd", label: "Your day end", pick: (d) => d.dayEnd },
  { id: "blkMealLunch", label: "Your lunch break", pick: (d) => d.meals.lunch || [] },
