  // Day-start / day-end draggable lines (each skipping its boundary column).
  overlay.appendChild(buildDayLine("start", state.dayStartMin, y, insetStart));
  overlay.appendChild(buildDayLine("end", dayEnd, y, insetEnd));

  return overlay;
}

