1	// Drafting a calendar from a whole programme, before anyone has said what they
2	// like.
3	//
4	// buildSchedule() answers "fit the shows I chose"; this answers the question a
5	// calendar-led planner asks instead — "every show is a candidate, so who gets
6	// 21:00 on Monday?" — and it answers it by scarcity: the contender with the
7	// fewest nights of its own takes the slot, because the one that plays again
8	// tomorrow can be caught tomorrow. A one-night-only show therefore beats a
9	// three-night one at the same hour, whatever either is.
10	//
11	// Nothing here knows which festival it is drafting, and nothing here touches
12	// the DOM: the slot shape, the clash rules and the travel maths are the
13	// engine's, and this module only decides who wins a contested hour and reports
14	// who lost it, so the surface above can offer the four verdicts back.
15	//
16	// Pure. Same inputs, same draft, every time.
17	
18	import { compatible, eligibleSlots, normalizeMealBreaks, slotKey, withinDayWindow } from "./engine.js";
19	
20	/**
21	 * Identity of one verdict against one performance: which show, which night.
22	 * The rejection sets are keyed by this, so rejecting Monday's showing of a run
23	 * leaves Tuesday's untouched.
24	 * @param {string} slug
25	 * @param {string} key a slotKey()
26	 * @returns {string}
27	 */
28	export function instanceKey(slug, key) {
29	  return `${slug}@${key}`;
30	}
31	
32	/**
33	 * The order contenders are ranked in, and the whole of the selection rule:
34	 * fewest performances of its own first, then the earlier start, then the
35	 * earlier finish, then the slug — the last three only so that two shows of
36	 * equal scarcity draft the same way every time.
37	 * @param {{freedom: number, start: number, end: number, slug: string}} a
38	 * @param {{freedom: number, start: number, end: number, slug: string}} b
39	 * @returns {number}
40	 */
41	export function byScarcity(a, b) {
42	  return (
43	    a.freedom - b.freedom ||
44	    a.start - b.start ||
45	    a.end - b.end ||
46	    a.slug.localeCompare(b.slug)
47	  );
48	}
49	
50	/**
51	 * Draft one performance per contested hour across the window, from every show
52	 * in the programme.
53	 *
54	 * Verdicts are honoured in the order they narrow the field: a rejected show
55	 * leaves the pool entirely, a rejected instance leaves that show's own pool, a
56	 * locked instance is placed before anything can take its hour, and a favourite
57	 * is placed before the unasked-for rest.
58	 *
59	 * `preferred` is weaker than any of them and is not a verdict: a taste the
60	 * reader stated, which orders the last pass and caps how much of a day may
61	 * come from outside it. It narrows nothing — an hour no preferred show wants
62	 * is still filled, up to that cap.
63	 *
64	 * @param {object[]} shows the whole catalogue
65	 * @param {{
66	 *   dateStart?: string, dateEnd?: string, windowStart?: string|Date, windowEnd?: string|Date,
67	 *   dayStartMin?: number, dayEndMin?: number,
68	 *   mealBreaks?: Array<object>, maxPerDay?: number,
69	 *   minGapSameVenue?: number, minGapDifferentVenue?: number, travelMode?: string,
70	 *   venueCoords?: Map<string,{lat:number,lng:number}>|object,
71	 *   locked?: Map<string,string>|Object<string,string>,
72	 *   favourites?: Set<string>|string[],
73	 *   rejectedShows?: Set<string>|string[],
74	 *   rejectedInstances?: Set<string>|string[],
75	 *   preferred?: Set<string>|string[],
76	 *   maxUnpreferredPerDay?: number,
77	 * }} [options]
78	 * @returns {{
79	 *   days: Array<{date: string, slots: object[]}>,
80	 *   picked: Map<string,string>,
81	 *   pool: Map<string, object[]>,
82	 *   crowdedOut: Array<{slug: string, title: string}>,
83	 *   counts: {candidates: number, contested: number, picked: number, shows: number},
84	 * }}
85	 */
86	export function draftCalendar(shows, options = {}) {
87	  const locked =
88	    options.locked instanceof Map
89	      ? new Map(options.locked)
90	      : new Map(Object.entries(options.locked ?? {}));
91	  const favourites = new Set(options.favourites ?? []);
92	  const rejectedShows = new Set(options.rejectedShows ?? []);
93	  const rejectedInstances = new Set(options.rejectedInstances ?? []);
94	  const preferred = new Set(options.preferred ?? []);
95	  // No stated taste means no cap: every show is as welcome as every other, so
96	  // an unpreferred-per-day limit would be a limit on nothing.
97	  const maxUnpreferredPerDay = preferred.size
98	    ? options.maxUnpreferredPerDay ?? Infinity
99	    : Infinity;
100	
101	  const gapOpts = {
102	    minGapSameVenue: options.minGapSameVenue,
103	    minGapDifferentVenue: options.minGapDifferentVenue,
104	    travelMode: options.travelMode,
105	  };
106	  const maxPerDay = options.maxPerDay ?? Infinity;
107	  const dayWindow = {
108	    dayStartMin: options.dayStartMin ?? 0,
109	    dayEndMin: options.dayEndMin ?? 1440,
110	    mealBreaks: normalizeMealBreaks(options.mealBreaks),
111	  };
112	
113	  const inPlay = (shows || []).filter((s) => !rejectedShows.has(s.slug));
114	  const all = eligibleSlots(inPlay, {
