import struct
f=open('product/requirements/shared/harness/vendor/systemfonts/NotoColorEmoji-req-subset.ttf','rb').read()
num=struct.unpack('>H',f[4:6])[0]
tabs={}
for i in range(num):
    off=12+16*i
    tag=f[off:off+4].decode('latin1'); o,l=struct.unpack('>II',f[off+8:off+16]); tabs[tag]=(o,l)
o,_=tabs['cmap']
n=struct.unpack('>H',f[o+2:o+4])[0]
chars=set()
for i in range(n):
    pid,eid,so=struct.unpack('>HHI',f[o+4+8*i:o+12+8*i])
    t=o+so; fmt=struct.unpack('>H',f[t:t+2])[0]
    if fmt==12:
        ng=struct.unpack('>I',f[t+12:t+16])[0]
        for g in range(ng):
            s,e,_g=struct.unpack('>III',f[t+16+12*g:t+28+12*g])
            for c in range(s,e+1): chars.add(c)
    elif fmt==4:
        segx2=struct.unpack('>H',f[t+6:t+8])[0]; seg=segx2//2
        ends=struct.unpack('>%dH'%seg,f[t+14:t+14+segx2])
        starts=struct.unpack('>%dH'%seg,f[t+16+segx2:t+16+2*segx2])
        for s,e in zip(starts,ends):
            if e==0xFFFF: continue
            for c in range(s,e+1): chars.add(c)
emo=sorted(c for c in chars if c>0x2000)
print(len(emo))
print(" ".join("%s U+%04X"%(chr(c),c) for c in emo))
