"use strict";
const { clickStackBand, jerusalemReady } = require("../../shared/case-helpers");

// Monday at 22:00: a one-night show took the hour from a free late-night that
// plays four evenings. Taking that one from the stack is a lock, and a lock is
// placed before the draft runs — so it seats the show the scarcity rule would
// never have picked, and the hour stops offering anyone.
const NIGHT = '.sch-day[data-date="2026-10-19"]';

module.exports = {
  description: "locking a night holds it, even against a scarcer contender",
  page: "/planJerusalem/",
  viewport: "desktop",
  ready: jerusalemReady,
  async capture(page, t) {
    const slot = page.locator(`${NIGHT} .sch-slot:has(.sch-stack)`).first();
    const frame = async () => t.clip(t.pad(await slot.boundingBox(), 8));
    const before = await frame();

    await clickStackBand(page, slot);
    await page.click("#calRivals .pop-rival");
    await page.waitForSelector(`${NIGHT} .sch-show--locked`);
    await page.waitForTimeout(250);

    const after = page.locator(`${NIGHT} .sch-slot:has(.sch-show--locked)`).first();
    return t.animate([before, await t.clip(t.pad(await after.boundingBox(), 8))]);
  },
};
=====VERDICTS 20.5 (stitch)=====
"use strict";
const { jerusalemReady, jerusalemVerdicts } = require("../../shared/case-helpers");

// Two nights side by side: Tuesday, where the draft is still guessing and both
// hours show what they turned down, and Wednesday, where one hour is locked.
// The lock is the one thing a card's face says beyond the show itself, and
// nothing on that night is on offer any more.
const OPEN = '.sch-day[data-date="2026-10-20"]';
const SETTLED = '.sch-day[data-date="2026-10-21"]';

module.exports = {
  description: "a locked card is marked as locked, and its hour stops offering anyone else",
  page: "/planJerusalem/",
  viewport: "desktop",
  localStorage: jerusalemVerdicts({ locked: { "noga-dangeli": "2026-10-21T21:00" } }),
  ready: jerusalemReady,
  async capture(page, t) {
    const boxes = [];
    for (const night of [OPEN, SETTLED]) {
      for (const slot of await page.locator(`${night} .sch-slot`).all()) boxes.push(await slot.boundingBox());
    }
    return t.clip(t.pad(t.union(boxes), 10));
  },
};
=====LOGIC TABLE 20.10=====
"use strict";

// The rows ARE the requirement: for each verdict, what it does to the show's
// pool of nights and when the drafter places it. verify() proves every row by
// running the shipped drafter over a programme built to make that row's effect
// the only thing that could explain the answer — nothing here is a list this
// repo keeps by hand.
const TABLE = {
  columns: ["Verdict", "What it does to the show's nights", "When the show is placed"],
  rows: [
    ["Lock this night", "all stay; that one is taken, your day hours and all", "first, before anything else"],
    ["Favourite the show", "all stay", "after the locks, before the undecided rest"],
    ["Not this night", "that night leaves", "with the rest, from what is left"],
    ["Not this show", "every night leaves", "never — and no block offers it either"],
    ["No verdict", "all stay", "with the rest, scarcest first"],
  ],
};

const COORDS = { H: { lat: 31.7806, lng: 35.2226 } };
const NIGHTS = ["2026-10-18", "2026-10-19", "2026-10-20"];

const show = (slug, nights, start = "20:00") => ({
  slug,
  title: slug,
  duration: 60,
